 async function saveAssessment(finish){const draft=currentDraft(),day=draft.data.inspection_date;if(draft.conflict){notice.textContent='다른 기기의 변경과 현재 입력을 비교한 뒤 저장해 주세요.';return false;}if(typeof day!=='string'||!/^\d{4}-(0[1-9]|1[0-2])-\d{2}$/.test(day)||Number(day.slice(0,4))<1||!Number.isFinite(Date.parse(day))||new Date(day).toISOString().slice(0,10)!==day){notice.textContent='점검일을 입력해 주세요.';body.querySelector('input[type=date]')?.focus();return false;}assessmentSaving=true;updateStatus();try{const value=await mutate('assessment',{form,subject_id:subject,answers:draft.data,complete:finish});if(value){draft.changed=false;draft.saveError=false;notice.textContent=finish?'평가를 완료 저장했습니다.':'입력 내용을 저장했습니다.';}return value||false;}catch(error){draft.saveError=true;throw error;}finally{assessmentSaving=false;updateStatus();}}
