 function assessmentStamp(value,kind,target){const canonical=v=>Array.isArray(v)?v.map(canonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):v;return JSON.stringify(canonical(value?.data?.assessments[kind+':'+target]?.draft?.data??null));}
 function adoptState(value,savedKey=null){
  const prefix=row.public_id+'|'+period+'|';
  for(const[key,draft]of drafts){if(!key.startsWith(prefix))continue;const parts=key.split('|'),stamp=assessmentStamp(value,parts[2],parts[3]);
   if(key===savedKey){draft.base=stamp;draft.changed=false;draft.conflict=false;draft.saveError=false;}
   else if(draft.changed){draft.conflict=draft.base!==stamp;}
   else if(draft.base!==stamp)drafts.delete(key);
  }
  state=value;walkthrough?.refresh();
 }
