 const materialContext=()=>row.public_id+'|'+period;
 function validMaterialOrigin(value){return value.context===materialContext()&&value.form===form&&value.subject===subject;}
 function rememberMaterialOrigin(id,origin){
  if(!origin)return;
  const criterion=origin.closest('.hyr-criterion');
  materialReturn={context:materialContext(),form,subject,criterion:criterion?.dataset.criterion||null,guide:origin===guide,evidence:id,open:common.open,search:commonBody.querySelector('input[type=search]')?.value||''};
  materialBack.hidden=false;
 }
 function restoreMaterialOrigin(){
  session();const value=materialReturn;materialReturn=null;materialBack.hidden=true;
  if(!value||!validMaterialOrigin(value))return;
  const search=commonBody.querySelector('input[type=search]');if(search){search.value=value.search;search.dispatchEvent(new Event('input'));}
  common.open=value.open;
  const card=[...body.querySelectorAll('.hyr-criterion')].find(e=>e.dataset.criterion===value.criterion),target=value.guide?guide:card||body;
  const check=card&&[...card.querySelectorAll('input[data-evidence]')].find(e=>e.dataset.evidence===value.evidence),focus=check?.closest('.hyr-proof-row')?.querySelector('button')||target;
  if(card){const details=card.querySelector('details');if(details)details.open=true;}
  if(focus===target)target.tabIndex=-1;
  focus.scrollIntoView({block:'center'});focus.focus({preventScroll:true});
 }
 function focusEvidence(id,origin){rememberMaterialOrigin(id,origin);common.open=true;const input=commonBody.querySelector('input[type=search]');input.value=labels.get(id);input.dispatchEvent(new Event('input'));const line=[...commonBody.querySelectorAll('.hyr-evidence')].find(e=>e.querySelector('input[data-evidence]')?.dataset.evidence===id);if(line){line.querySelector('details').open=true;line.scrollIntoView({block:'start'});line.querySelector('.hyr-monthly-find')?.click();}}
 function renderGuide(){if(!state)return;guide.replaceChildren(N('strong','다음에 확인할 서류'));
  const relevant=new Map();let missing=0;for(const key of catalog.order){const schema=catalog.forms[key],subjects=schema.needs_subject?state.data.subjects[key].map(s=>s.id):['site'];for(const who of subjects){const local=drafts.get(row.public_id+'|'+period+'|'+key+'|'+who),answers=local?.data.answers||state.data.assessments[key+':'+who]?.draft?.data.answers||{};for(const criterion of schema.criteria){const ungraded=answers[criterion.id]?.value==null;if(ungraded)missing++;for(const id of criterion.evidence)if(!evidenceState(id).checked){const value=relevant.get(id)||{count:0,forms:new Set()};value.count+=ungraded?2:1;value.forms.add(schema.title);relevant.set(id,value);}}}}
  const next=[...relevant].sort((a,b)=>b[1].count-a[1].count)[0];if(next){guide.append(N('p',labels.get(next[0])+' · '+[...next[1].forms].join(', ')),B('자료 확인하기',()=>focusEvidence(next[0],guide)));}else guide.append(N('p',missing?'자료 확인 후 아직 평가하지 않은 '+missing+'개 항목을 입력해 주세요.':'평가대상자와 각 평가의 저장 상태를 확인해 주세요.'));
  const unassigned=['manager','supervisor'].filter(k=>!state.data.subjects[k].length).map(k=>catalog.forms[k].title);if(unassigned.length)guide.append(N('p',unassigned.join('·')+' 대상자를 추가해 주세요.','hyr-help'));
 }
