 async function downloadBlank(){if(busy)return;lock(true);try{const r=await fetch(origin+base+scope()+'/templates/'+form+query(),{cache:'no-store',headers:{Authorization:'Bearer '+token}});session();if(!r.ok)throw Error('출력용 양식을 받지 못했습니다.');const url=URL.createObjectURL(await r.blob()),a=N('a');urls.add(url);a.href=url;a.download=catalog.forms[form].title+'_출력용.'+catalog.forms[form].format;a.click();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url);},30000);}finally{lock(false);}}
 const jobLabels={QUEUED:'판독 대기',RUNNING:'이 PC에서 판독 중',READY:'전자평가표 초안 반영',NEEDS_REVIEW:'판독 결과 확인 필요',APPLIED:'확인한 값 반영'};
