  const mode=N('select');mode.setAttribute('aria-label','평가 입력 방법');for(const[value,label]of[['SCREEN','화면에서 평가'],['PAPER','종이 평가표 보고 입력'],['PAPER_PDF','PDF 판독 후 확인']])mode.append(new Option(label,value));mode.value=data.entry_mode;mode.onchange=()=>{data.entry_mode=mode.value;mark();};box.append(N('strong','종이·PDF 평가표'),mode,B('출력용 양식 받기',downloadBlank));
